namespace fs = std::filesystem;
struct Handle { HANDLE h=nullptr; Handle()=default; explicit Handle(HANDLE x):h(x){} ~Handle(){if(h&&h!=INVALID_HANDLE_VALUE)CloseHandle(h);} Handle(const Handle&)=delete;Handle& operator=(const Handle&)=delete; HANDLE get()const{return h;} HANDLE release(){auto x=h;h=nullptr;return x;} explicit operator bool()const{return h&&h!=INVALID_HANDLE_VALUE;} };
static uint64_t ticks(FILETIME f){ULARGE_INTEGER u{};u.LowPart=f.dwLowDateTime;u.HighPart=f.dwHighDateTime;return u.QuadPart;}
static uint64_t now(){FILETIME f;GetSystemTimeAsFileTime(&f);return ticks(f);}
static std::wstring lower(std::wstring s){std::transform(s.begin(),s.end(),s.begin(),[](wchar_t c){return std::towlower(c);});return s;}
static std::wstring fullpath(const std::wstring& s){DWORD n=GetFullPathNameW(s.c_str(),0,nullptr,nullptr);if(!n)return {};std::wstring b(n,L'\0');DWORD got=GetFullPathNameW(s.c_str(),n,b.data(),nullptr);if(!got||got>=n)return {};b.resize(got);return lower(b);}
static std::wstring procpath(HANDLE h){std::wstring b(32768,L'\0');DWORD n=(DWORD)b.size();if(!QueryFullProcessImageNameW(h,0,b.data(),&n))return {};b.resize(n);return lower(b);}
static uint64_t birth(HANDLE h){FILETIME c,e,k,u;if(!GetProcessTimes(h,&c,&e,&k,&u))return 0;return ticks(c);}
static std::wstring quote(const std::wstring& s){std::wstring r=L"\"";unsigned bs=0;for(wchar_t c:s){if(c==L'\\'){++bs;continue;}if(c==L'\"'){r.append(bs*2+1,L'\\');r+=c;bs=0;continue;}r.append(bs,L'\\');bs=0;r+=c;}r.append(bs*2,L'\\');return r+L"\"";}
static std::string utf8(const std::wstring& w){if(w.empty())return {};int n=WideCharToMultiByte(CP_UTF8,0,w.data(),(int)w.size(),nullptr,0,nullptr,nullptr);if(n<=0)return {};std::string b(n,'\0');WideCharToMultiByte(CP_UTF8,0,w.data(),(int)w.size(),b.data(),n,nullptr,nullptr);return b;}
static std::string esc(const std::string& s){std::string o;for(unsigned char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c<32){char b[7];sprintf_s(b,"\\u%04x",(unsigned)c);o+=b;}else o+=char(c);}}return o;}
static std::wstring data_dir(){wchar_t b[32768];DWORD n=GetEnvironmentVariableW(L"LOCALAPPDATA",b,32768);if(n&&n<32768)return std::wstring(b,n)+L"\\RawrXD\\snap";return L".\\snap";}
static bool atomic_record(const fs::path& p,const std::string& content){std::error_code ec;fs::create_directories(p.parent_path(),ec);if(ec)return false;auto temp=p;temp+=L".tmp."+std::to_wstring(GetCurrentProcessId());{std::ofstream f(temp,std::ios::binary|std::ios::trunc);if(!f)return false;f<<content;f.flush();if(!f)return false;}if(!MoveFileExW(temp.c_str(),p.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){fs::remove(temp,ec);return false;}return true;}
static void event(const std::wstring& dir,const std::string& name,DWORD pid=0,const std::string& detail=""){fs::path p=fs::path(dir)/L"events.jsonl";std::error_code ec;fs::create_directories(p.parent_path(),ec);Handle lock(CreateMutexW(nullptr,FALSE,L"Local\\RawrXD_SNAP_ESP_Log_v1"));if(lock)WaitForSingleObject(lock.get(),INFINITE);{std::ofstream f(p,std::ios::binary|std::ios::app);if(f)f<<"{\"time_filetime\":"<<now()<<",\"event\":\""<<esc(name)<<"\",\"pid\":"<<pid<<",\"detail\":\""<<esc(detail)<<"\"}\n";}if(lock)ReleaseMutex(lock.get());std::cout<<"[SNAP] "<<name<<" pid="<<pid<<" "<<detail<<"\n";}
struct Record{DWORD pid=0;uint64_t created=0;std::wstring exe;DWORD owner=0;uint64_t owner_created=0;};
static fs::path recordpath(const std::wstring& d,DWORD pid){return fs::path(d)/(L"session_"+std::to_wstring(pid)+L".txt");}
static bool readrec(const fs::path& p,Record& r){std::ifstream f(p,std::ios::binary);if(!f)return false;std::string line;try{if(!std::getline(f,line)||line!="SNAP1")return false;if(!std::getline(f,line))return false;r.pid=std::stoul(line);if(!std::getline(f,line))return false;r.created=std::stoull(line);if(!std::getline(f,line))return false;r.owner=std::stoul(line);if(!std::getline(f,line))return false;r.owner_created=std::stoull(line);if(!std::getline(f,line))return false;int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,line.data(),(int)line.size(),nullptr,0);if(n<=0)return false;r.exe.resize(n);MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,line.data(),(int)line.size(),r.exe.data(),n);}catch(...){return false;}return r.pid&&r.created&&r.owner&&r.owner_created&&!r.exe.empty();}
static bool writerec(const std::wstring& dir,const Record& r){std::ostringstream o;o<<"SNAP1\n"<<r.pid<<"\n"<<r.created<<"\n"<<r.owner<<"\n"<<r.owner_created<<"\n"<<utf8(r.exe)<<"\n";return atomic_record(recordpath(dir,r.pid),o.str());}
static bool matches(HANDLE h,const Record& r){return birth(h)==r.created && procpath(h)==r.exe;}
static bool alive(HANDLE h){DWORD e=0;return GetExitCodeProcess(h,&e)&&e==STILL_ACTIVE;}
static bool owner_alive(const Record& r){Handle h(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,r.owner));return h&&birth(h.get())==r.owner_created&&alive(h.get());}
static void scan(const std::wstring& dir){std::error_code ec;fs::create_directories(dir,ec);if(ec){std::cerr<<"directory unavailable\n";return;}for(auto& e:fs::directory_iterator(dir,ec)){if(ec)break;if(!e.is_regular_file()||e.path().extension()!=L".txt"||e.path().filename().wstring().rfind(L"session_",0)!=0)continue;Record r;if(!readrec(e.path(),r)){event(dir,"INVALID_RECORD",0,utf8(e.path().filename().wstring()));continue;}Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,r.pid));if(!p){event(dir,"PROCESS_ABSENT_OR_INACCESSIBLE",r.pid);continue;}if(!matches(p.get(),r)){event(dir,"PID_REUSED_OR_IDENTITY_MISMATCH",r.pid);continue;}if(!alive(p.get())){event(dir,"PROCESS_EXITED",r.pid);continue;}PROCESS_MEMORY_COUNTERS pm{};pm.cb=sizeof(pm);std::string d="owner_alive="+std::to_string(owner_alive(r))+" working_set_mb=";if(GetProcessMemoryInfo(p.get(),&pm,sizeof(pm)))d+=std::to_string(pm.WorkingSetSize/(1024*1024));else d+="unknown";event(dir,owner_alive(r)?"OWNED_ACTIVE":"ORPHAN_CANDIDATE",r.pid,d);}}
static int cleanup(const std::wstring& dir,DWORD pid,bool confirm){Record r;if(!readrec(recordpath(dir,pid),r)||r.pid!=pid){std::cerr<<"No valid ownership record\n";return 3;}Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|PROCESS_TERMINATE|SYNCHRONIZE,FALSE,pid));if(!p||!matches(p.get(),r)||!alive(p.get())){std::cerr<<"Process identity mismatch, exited, or inaccessible\n";return 4;}if(owner_alive(r)){std::cerr<<"Refusing: supervisor still alive\n";return 5;}if(!confirm){event(dir,"CLEANUP_DRY_RUN",pid,"add --confirm to terminate verified orphan");return 0;}if(!TerminateProcess(p.get(),0x534E4150)){std::cerr<<"TerminateProcess failed "<<GetLastError()<<"\n";return 6;}DWORD w=WaitForSingleObject(p.get(),10000);if(w!=WAIT_OBJECT_0){event(dir,"CLEANUP_WAIT_FAILED",pid);return 7;}event(dir,"ORPHAN_TERMINATED",pid);std::error_code ec;fs::remove(recordpath(dir,pid),ec);return 0;}
static int run(const std::wstring& dir,const std::wstring& exe,const std::vector<std::wstring>& args,DWORD stall_ms,const std::wstring& progress){auto path=fullpath(exe);if(path.empty()||!fs::is_regular_file(path)){std::cerr<<"Executable not found\n";return 2;}Handle job(CreateJobObjectW(nullptr,nullptr));if(!job){std::cerr<<"CreateJobObject failed\n";return 3;}JOBOBJECT_EXTENDED_LIMIT_INFORMATION lim{};lim.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if(!SetInformationJobObject(job.get(),JobObjectExtendedLimitInformation,&lim,sizeof(lim))){std::cerr<<"SetInformationJobObject failed\n";return 4;}std::wstring cmd=quote(path);for(const auto& a:args)cmd+=L" "+quote(a);std::vector<wchar_t> mutable_cmd(cmd.begin(),cmd.end());mutable_cmd.push_back(0);STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};std::wstring work=fs::path(path).parent_path().wstring();if(!CreateProcessW(path.c_str(),mutable_cmd.data(),nullptr,nullptr,FALSE,CREATE_SUSPENDED|CREATE_NEW_PROCESS_GROUP|CREATE_NO_WINDOW,nullptr,work.c_str(),&si,&pi)){std::cerr<<"CreateProcess failed "<<GetLastError()<<"\n";return 5;}Handle process(pi.hProcess),thread(pi.hThread);if(!AssignProcessToJobObject(job.get(),process.get())){event(dir,"JOB_ASSIGN_FAILED",pi.dwProcessId,std::to_string(GetLastError()));TerminateProcess(process.get(),1);WaitForSingleObject(process.get(),10000);return 6;}Record r{pi.dwProcessId,birth(process.get()),procpath(process.get()),GetCurrentProcessId(),0};Handle self(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,r.owner));r.owner_created=self?birth(self.get()):0;if(!r.created||r.exe!=path||!r.owner_created||!writerec(dir,r)){event(dir,"RECORD_FAILED",r.pid);TerminateProcess(process.get(),1);WaitForSingleObject(process.get(),10000);return 7;}if(ResumeThread(thread.get())==(DWORD)-1){event(dir,"RESUME_FAILED",r.pid);TerminateProcess(process.get(),1);WaitForSingleObject(process.get(),10000);return 8;}event(dir,"STARTED",r.pid,"job=kill_on_close exe="+utf8(path));auto last=std::chrono::steady_clock::now();fs::file_time_type previous{};bool has_previous=false;while(true){DWORD w=WaitForSingleObject(process.get(),1000);if(w==WAIT_OBJECT_0)break;if(w!=WAIT_TIMEOUT){event(dir,"WAIT_ERROR",r.pid,std::to_string(GetLastError()));return 9;}if(!progress.empty()&&stall_ms){std::error_code ec;auto t=fs::last_write_time(progress,ec);if(!ec&&(!has_previous||t!=previous)){previous=t;has_previous=true;last=std::chrono::steady_clock::now();}auto elapsed=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-last).count();if(elapsed>stall_ms){event(dir,"PROGRESS_STALLED",r.pid,"elapsed_ms="+std::to_string(elapsed)+" warning_only=1");last=std::chrono::steady_clock::now();}}}DWORD code=1;GetExitCodeProcess(process.get(),&code);event(dir,"EXITED",r.pid,"exit_code="+std::to_string(code));std::error_code ec;fs::remove(recordpath(dir,r.pid),ec);return code==0?0:10;}
static void usage(){std::wcout<<L"SNAP supervisor (Win32, no third-party dependencies)\n  snap_supervisor scan [--state DIR]\n  snap_supervisor cleanup PID [--confirm] [--state DIR]\n  snap_supervisor run [--state DIR] [--progress FILE --stall-ms N] -- EXE [ARGS...]\n";}
int wmain(int argc,wchar_t** argv){if(argc<2){usage();return 1;}std::wstring mode=argv[1],dir=data_dir(),progress;DWORD stall=0,pid=0;bool confirm=false;std::vector<std::wstring> child;bool separator=false;for(int i=2;i<argc;++i){std::wstring a=argv[i];if(separator){child.push_back(a);continue;}if(a==L"--"){separator=true;continue;}if(a==L"--state"&&i+1<argc){dir=argv[++i];continue;}if(a==L"--progress"&&i+1<argc){progress=argv[++i];continue;}if(a==L"--stall-ms"&&i+1<argc){try{stall=std::stoul(argv[++i]);}catch(...){return 1;}continue;}if(a==L"--confirm"){confirm=true;continue;}if(mode==L"cleanup"&&!pid){try{pid=std::stoul(a);}catch(...){return 1;}continue;}usage();return 1;}if(mode==L"scan"){scan(dir);return 0;}if(mode==L"cleanup"&&pid)return cleanup(dir,pid,confirm);if(mode==L"run"&&!child.empty()){auto exe=child.front();child.erase(child.begin());return run(dir,exe,child,stall,progress);}usage();return 1;}
